<?php
require __DIR__.'/../../config/bootstrap.php';
use Pharmacy\Auth\Authorization;use Pharmacy\Patients\ExternalPatientRepository;use Pharmacy\Support\Csrf;
Authorization::requireRole('ADMIN','PHARMACIST');$repo=new ExternalPatientRepository($pdo);$message=$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{Csrf::validate((string)($_POST['csrf']??''));$repo->save(['name'=>trim($_POST['name']??''),'age'=>($_POST['age']??'')!==''?(int)$_POST['age']:null,'gender'=>trim($_POST['gender']??''),'phone'=>trim($_POST['phone']??''),'address'=>trim($_POST['address']??''),'notes'=>trim($_POST['notes']??''),'active'=>1]);$message='External patient saved.';}catch(Throwable $e){$error=$e->getMessage();}}
$q=trim($_GET['q']??'');$rows=$repo->search($q,100);$title='External Patients';require __DIR__.'/../../templates/header.php';?>
<h2 class="page-title">External Patients</h2><?php if($message):?><div data-flash="<?=htmlspecialchars($message)?>"></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="row g-3"><div class="col-lg-4"><div class="card"><div class="card-body"><h5>Register Patient</h5><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(Csrf::token())?>"><div class="mb-2"><label class="form-label">Name</label><input class="form-control" name="name" required></div><div class="row"><div class="col"><label class="form-label">Age</label><input class="form-control" type="number" min="0" max="120" name="age"></div><div class="col"><label class="form-label">Gender</label><input class="form-control" name="gender"></div></div><div class="mb-2 mt-2"><label class="form-label">Phone</label><input class="form-control" name="phone"></div><div class="mb-2"><label class="form-label">Address</label><textarea class="form-control" name="address"></textarea></div><button class="btn btn-dark">Save</button></form></div></div></div><div class="col-lg-8"><form class="mb-2"><input class="form-control" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search name, patient ID or phone"></form><div class="card"><div class="card-body"><table class="table datatable"><thead><tr><th>Patient ID</th><th>Name</th><th>Age</th><th>Phone</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['patient_code'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars((string)($r['age']??''))?></td><td><?=htmlspecialchars($r['phone']??'')?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require __DIR__.'/../../templates/footer.php';
